// ── Prove + Verify main ───────────────────────────────────────────────────────

pub fn main() {
    tracing_subscriber::fmt::init();

    let (public, private) = load_inputs();
    let csc_pubkey = private.pv.csc_pubkey.to_vec();
    let buf = pack_preparsed_passport(&private.dg1[..private.dg1_padded_length as usize], &private.pv);

    info!("Loaded passport inputs successfully");
    info!(
        "  Age range: [{}, {}]",
        public.min_age_required, public.max_age_required
    );
    info!("  Preparsed buffer size: {} bytes", buf.len());

    // ── Compile guest ──
    let target_dir = "/tmp/jolt-guest-targets";
    let mut program = guest::compile_complete_age_check(target_dir);

    // ── Preprocess ──
    let shared_preprocessing = guest::preprocess_shared_complete_age_check(&mut program);
    let prover_preprocessing =
        guest::preprocess_prover_complete_age_check(shared_preprocessing.clone());
    let verifier_setup = prover_preprocessing.generators.to_verifier_setup();
    let blindfold_setup = prover_preprocessing.blindfold_setup();
    let verifier_preprocessing = guest::preprocess_verifier_complete_age_check(
        shared_preprocessing,
        verifier_setup,
        Some(blindfold_setup),
    );

    let prove = guest::build_prover_complete_age_check(program, prover_preprocessing);
    let verify = guest::build_verifier_complete_age_check(verifier_preprocessing);

    // ── Prove ──
    info!("Starting proof generation...");
    let now = Instant::now();
    let (output, proof, io_device) = prove(
        public.current_date,
        public.min_age_required,
        public.max_age_required,
        csc_pubkey.clone(),
        jolt_sdk::PrivateInput::new(buf.clone()),
    );
    let prove_time = now.elapsed();
    info!("Prove time: {:.3} s", prove_time.as_secs_f64());
    info!("Output: {output}");

    // ── Verify ──
    info!("Starting verification...");
    let now = Instant::now();
    let is_valid = verify(
        public.current_date,
        public.min_age_required,
        public.max_age_required,
        csc_pubkey,
        output,
        io_device.panic,
        proof,
    );
    let verify_time = now.elapsed();
    info!("Verify time: {:.3} s", verify_time.as_secs_f64());
    info!("Valid: {is_valid}");
    assert!(is_valid);
}
